insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_12_v1'
from (values
('128.36.c.1.A',2,'When a speaker''s voice rises at the end of a sentence in English, the sentence is often:','["a question", "a title", "a command", "an exclamation"]'::jsonb,0,'Rising intonation usually signals a question.','original'),
('128.36.c.1.A',2,'Which pair of words differs only in the vowel sound?','["book and pen", "ship and sheep", "cat and dog", "sun and moon"]'::jsonb,1,'The vowel sounds change the word.','original'),
('128.36.c.1.B',1,'English text is read:','["bottom to top", "in a circle", "left to right and top to bottom", "right to left"]'::jsonb,2,'Print direction in English runs left to right.','original'),
('128.36.c.1.B',1,'A learner begins reading a page of English. Where should the learner start?','["at the bottom right", "at the last word", "in the middle", "at the top left"]'::jsonb,3,'Reading starts at the top left.','original'),
('128.36.c.1.C',1,'Which letter makes the first sound in the word ''sun''?','["s", "p", "t", "m"]'::jsonb,0,'The word sun begins with the letter s.','original'),
('128.36.c.1.C',1,'The letters ''sh'' together make the sound in:','["chair", "ship", "cat", "thin"]'::jsonb,1,'Sh makes the /sh/ sound.','original'),
('128.36.c.1.D',2,'Which word names a number answer after adding in math class?','["map", "verb", "sum", "rhyme"]'::jsonb,2,'The sum is the result of addition.','original'),
('128.36.c.1.D',2,'Which word names something you do with a ruler in class?','["sleep", "whisper", "paint", "measure"]'::jsonb,3,'A ruler is used to measure.','original'),
('128.36.c.1.E',2,'A teacher says: ''Please open your books to page ten.'' What should students do?','["open their books to page ten", "close the door", "line up for lunch", "sharpen a pencil"]'::jsonb,0,'The direction tells students what to do.','original'),
('128.36.c.1.E',2,'A listener hears: ''The bus is late, so we will start class in ten minutes.'' The main point is:','["class is canceled", "class will begin later", "lunch is early", "the bus is new"]'::jsonb,1,'The main point is the delay.','original'),
('128.36.c.1.F',1,'Which day comes after Monday?','["Wednesday", "Sunday", "Tuesday", "Friday"]'::jsonb,2,'Tuesday follows Monday.','original'),
('128.36.c.1.F',1,'Which word names a place in a school?','["teacher", "reading", "pencil", "library"]'::jsonb,3,'A library is a place.','original'),
('128.36.c.1.G',2,'To read the word ''cat'', a learner blends the sounds:','["/k/ /a/ /t/", "/b/ /a/ /t/", "/t/ /a/ /k/", "/c/ /o/ /d/"]'::jsonb,0,'Blending joins sounds in order.','original'),
('128.36.c.1.G',2,'Which word has the short a sound as in ''map''?','["bee", "bag", "boat", "bike"]'::jsonb,1,'Bag has the short a sound.','original'),
('128.36.c.1.H',1,'Which word tells a direction?','["happy", "jump", "left", "table"]'::jsonb,2,'Left is a direction.','original'),
('128.36.c.1.H',1,'In ''The book is under the desk,'' the word under tells:','["size", "time", "color", "position"]'::jsonb,3,'Under shows where the book is.','original'),
('128.36.c.1.I',1,'A red octagon sign with white letters most likely says:','["STOP", "SLOW", "OPEN", "GO"]'::jsonb,0,'The shape and color are used for stop signs.','original'),
('128.36.c.1.I',1,'A sign on a door says EXIT. It tells people:','["where to park a bike", "where to leave the building", "where to buy lunch", "where to sleep"]'::jsonb,1,'Environmental print gives information.','original'),
('128.36.c.1.J',2,'A bilingual dictionary helps a learner by:','["drawing a map", "grading the test", "giving a word''s meaning in two languages", "writing the homework"]'::jsonb,2,'Bilingual dictionaries translate words.','original'),
('128.36.c.1.J',2,'To check how to say a new English word, a learner can use:','["a calendar", "a clock", "a ruler", "an online dictionary with audio"]'::jsonb,3,'Audio dictionaries model pronunciation.','original'),
('128.36.c.1.K',2,'A learner does not understand a direction. A polite way to ask is:','["Could you please repeat that?", "Be quiet.", "I don''t care.", "That''s silly."]'::jsonb,0,'Polite questions clarify meaning.','original'),
('128.36.c.1.K',2,'Which shows active listening?','["looking out the window", "looking at the speaker and nodding", "drawing on the desk", "talking to a friend"]'::jsonb,1,'Active listeners show attention.','original'),
('128.36.c.1.L',2,'A learner tells a partner how people greet each other in the learner''s home country. This is:','["taking a test", "spelling a word", "sharing prior knowledge", "copying a text"]'::jsonb,2,'Sharing experience builds communication.','original'),
('128.36.c.1.L',2,'Respect for classmates'' cultures grows when learners:','["ignore differences", "laugh at accents", "avoid talking", "listen to each other''s experiences"]'::jsonb,3,'Listening builds respect.','original'),
('128.36.c.2.A',2,'After reading a short story, a learner tells the main events in a few sentences. This is:','["retelling", "copying", "erasing", "spelling"]'::jsonb,0,'A retell restates events in order.','original'),
('128.36.c.2.A',2,'A beginning English learner may retell a story using:','["silence only", "English or the home language as needed", "no words", "a different story"]'::jsonb,1,'Retelling can use the home language for support.','original'),
('128.36.c.2.B',2,'Looking at pictures before reading helps a learner to:','["finish quicker", "skip the title", "predict what the text is about", "avoid the words"]'::jsonb,2,'Illustrations support understanding.','original'),
('128.36.c.2.B',2,'A graphic organizer before reading is used to:','["count pages", "erase the text", "hide the title", "sort ideas and vocabulary"]'::jsonb,3,'Organizers prepare readers.','original'),
('128.36.c.2.C',2,'During shared reading, learners:','["read together and answer questions", "read alone silently", "sleep at desks", "copy the answers"]'::jsonb,0,'Shared reading is interactive.','original'),
('128.36.c.2.C',2,'A learner shows comprehension by:','["turning pages quickly", "answering a question about what was read", "staring at the page", "reading the cover"]'::jsonb,1,'Responding shows understanding.','original'),
('128.36.c.2.D',2,'A story about a family market reminds a learner of a market in her town. This is a connection to:','["a rhyme", "a dictionary", "personal experience", "the index"]'::jsonb,2,'The learner links text to life.','original'),
('128.36.c.2.D',2,'Linking a story to an event in the community is a connection to:','["the page number", "the font", "the cover color", "the larger community"]'::jsonb,3,'Community connections link text to the world.','original'),
('128.36.c.2.E',2,'A learner watches a short video about weather and then explains it. This shows learning by:','["listening to media", "taking a spelling test", "playing a gym game", "doing a math drill"]'::jsonb,0,'Media can teach new ideas.','original'),
('128.36.c.2.E',2,'Watching a video with captions helps a learner to:','["forget the words", "connect spoken words to written words", "avoid listening", "stop reading"]'::jsonb,1,'Captions pair sound and print.','original'),
('128.36.c.2.F',2,'A boy brings an umbrella and wears a raincoat. A learner can infer that:','["it is a holiday", "he is hungry", "it may rain", "school is closed"]'::jsonb,2,'Details suggest the weather.','original'),
('128.36.c.2.F',2,'To support an inference, a learner can point to:','["the cover price", "the page number", "a guess", "a detail in the text or picture"]'::jsonb,3,'Inferences need evidence.','original'),
('128.36.c.3.A',1,'A thumbs-up after a classmate''s answer is:','["non-verbal feedback", "a math fact", "a title", "a spelling rule"]'::jsonb,0,'Gestures give feedback without words.','original'),
('128.36.c.3.A',1,'Which is positive verbal feedback?','["That''s wrong.", "Good job explaining that.", "I''m bored.", "Be quiet."]'::jsonb,1,'Encouraging words help speakers.','original'),
('128.36.c.3.B',3,'Which sentence is more complex?','["It rained.", "We went.", "Because it was raining, we stayed inside.", "We stayed."]'::jsonb,2,'It joins two ideas with a clause.','original'),
('128.36.c.3.B',3,'A learner who moves from ''I go store'' to ''I went to the store yesterday'' is:','["using fewer words", "using only gestures", "using silence", "using more complete grammar"]'::jsonb,3,'Language grows in complexity.','original'),
('128.36.c.3.C',2,'Which question asks for an address?','["Where do you live?", "How old are you?", "What time is it?", "What is your name?"]'::jsonb,0,'An address tells where someone lives.','original'),
('128.36.c.3.C',2,'A new student says, ''I am from Mexico.'' The student is giving:','["a weather report", "information about nationality or origin", "a math problem", "a direction"]'::jsonb,1,'The student tells where he or she is from.','original'),
('128.36.c.3.D',1,'Which phrase expresses gratitude?','["Excuse me.", "Good morning.", "Thank you very much.", "I don''t know."]'::jsonb,2,'Thank you shows gratitude.','original'),
('128.36.c.3.D',1,'A learner says, ''I need help with this word.'' The learner is expressing:','["a goodbye", "a joke", "a greeting", "a need"]'::jsonb,3,'The statement asks for support.','original'),
('128.36.c.3.E',2,'Shaking hands when meeting a teacher at a formal event is:','["non-verbal communication", "a math sign", "a written message", "a spelling pattern"]'::jsonb,0,'Gestures communicate without speech.','original'),
('128.36.c.3.E',2,'Looking at the speaker shows:','["confusion", "attention and respect", "anger", "boredom"]'::jsonb,1,'Eye contact signals respect in many settings.','original'),
('128.36.c.3.F',2,'A beginner who says ''I like'' and points to a picture is:','["reading a map", "refusing to answer", "expressing an opinion with simple language", "writing a report"]'::jsonb,2,'Early learners combine words and gestures.','original'),
('128.36.c.3.F',2,'Which sentence gives an opinion?','["The story has five pages.", "The story is in a book.", "The story was printed last year.", "I think the story is exciting."]'::jsonb,3,'Opinions express a view.','original'),
('128.36.c.3.G',2,'After listening to a recording about animals, a learner answers a question aloud. This is:','["responding orally to information", "spelling a list", "copying a sentence", "coloring a map"]'::jsonb,0,'The learner speaks about what was heard.','original'),
('128.36.c.3.G',2,'A learner reads a short chart and tells a partner what it shows. This is:','["singing a song", "speaking about print information", "drawing a flag", "writing a poem"]'::jsonb,1,'The learner responds orally to print.','original'),
('128.36.c.3.H',2,'A Venn diagram is used to:','["tell time", "spell words", "show how two things are alike and different", "count syllables"]'::jsonb,2,'It organizes comparisons.','original'),
('128.36.c.3.H',2,'A word web helps a learner:','["measure a line", "erase mistakes", "time a speech", "organize ideas around a topic"]'::jsonb,3,'Webs show related ideas.','original'),
('128.36.c.4.A',2,'Two learners compare holidays in their home countries. They are:','["comparing characteristics of cultures", "copying a text", "spelling a list", "taking a test"]'::jsonb,0,'They study similarities and differences in cultures.','original'),
('128.36.c.4.A',2,'A picture of a festival and a short text about it can show:','["the rules of math", "traditions of a culture", "the steps of a lab", "the parts of a plant"]'::jsonb,1,'Texts and images reveal culture.','original'),
('128.36.c.4.B',2,'A folktale told for many generations is called:','["a text message", "a weather report", "a traditional story", "a bus schedule"]'::jsonb,2,'Traditional stories pass down through time.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
